function toQueryString(query: Record<string, unknown> | undefined): string {
  if (!query) return "";
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value === undefined || value === null || value === "") continue;
    if (Array.isArray(value)) {
      const values = value.filter((item) => item !== undefined && item !== null && item !== "");
      if (values.length) params.set(key, values.join(","));
      continue;
    }
    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
      params.set(key, String(value));
    }
  }
  const serialized = params.toString();
  return serialized ? `?${serialized}` : "";
}

function replacePathParameters(
  path: string,
  parameters: Record<string, string | number> | undefined,
): string {
  return path.replace(/:([A-Za-z_$][\w$]*)/g, (_match, name: string) => {
    const value = parameters?.[name];
    if (value === undefined || value === null) {
      throw new Error(`Falta el parámetro de ruta "${name}".`);
    }
    return encodeURIComponent(String(value));
  });
}

